diff --git a/src/ui/rename-dialog.tsx b/src/ui/rename-dialog.tsx
index e01aa42..5d7b990 100644
--- a/src/ui/rename-dialog.tsx
+++ b/src/ui/rename-dialog.tsx
@@ -12,12 +12,24 @@ export function RenameDialog({ current, onSubmit, onCancel }: Props) {
   const [value, setValue] = useState(current);
   const [error, setError] = useState<string | null>(null);
+  // Close on Escape so the dialog is fully keyboard-operable.
+  const onKeyDown = (e: KeyboardEvent) => {
+    if (e.key === 'Escape') onCancel();
+  };
   return (
-    <div class="dialog">
-      <input value={value} onInput={(e) => setValue(e.currentTarget.value)} />
-      {error && <span class="error">{error}</span>}
+    <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="rename-title" onKeyDown={onKeyDown}>
+      <h2 id="rename-title">Rename item</h2>
+      <label for="rename-input">New name</label>
+      <input
+        id="rename-input"
+        value={value}
+        aria-invalid={error !== null}
+        aria-describedby={error !== null ? 'rename-error' : undefined}
+        onInput={(e) => setValue(e.currentTarget.value)}
+      />
+      {error && <span id="rename-error" role="alert" class="error">{error}</span>}
       <button onClick={() => onSubmit(value)}>Rename</button>
+      <button onClick={onCancel}>Cancel</button>
     </div>
   );
 }
